INSERT INTO P_HISTORY (
  	historyid
  	,productid
  	,usrno
  	,bfrpnm
  	,updnm
  	,bfrprice
  	,updprice
  	,bfrtitle
  	,updtitle
  	,bfrcont
  	,updtcont
  	,bfrqty
  	,updtqty
  	,rdate
) VALUES (
	p_history_seq.NEXTVAL
	,#{oivo.productid}
	,#{ovo.usrno}
	,#{oivo.pnm}
	,#{oivo.pnm}
	,#{oivo.price}
	,#{oivo.price}
	,#{oivo.title}
	,#{oivo.title}
	,#{oivo.cont}
	,#{oivo.cont}
	,#{oivo.pqty}
	,#{oivo.pqty} - #{oivo.qty}
	,sysdate
)
